def _fail_budget(repo, speculative):
    """Make every DynamoDB call touching the budget resource fail."""
    if speculative:
        real = repo.speculative_consume

        def speculative_consume(entity_id, resource, consume, *args, **kwargs):
            if resource == "budget":
                raise RuntimeError("throttled")
            return real(entity_id, resource, consume, *args, **kwargs)

        repo.speculative_consume = speculative_consume
    else:
        real_fetch = repo.batch_get_entity_and_buckets

        def batch_get_entity_and_buckets(entity_id, bucket_keys):
            if any(key[1] == "budget" for key in bucket_keys):
                raise RuntimeError("throttled")
            return real_fetch(entity_id, bucket_keys)

        repo.batch_get_entity_and_buckets = batch_get_entity_and_buckets


class TestFastAndSlowTogether:
    """``search`` admitted on the fast path, ``budget`` sent to the slow path."""

    @staticmethod
    def _budget_needs_the_slow_path(repo, capacity):
        repo.set_limits("user", [Limit.custom("weekly", capacity, **SLOW)], "budget")

    def test_the_fast_win_is_kept_and_the_rest_committed(self, repo):
        limiter = SyncRateLimiter(repository=repo)
        _admit(limiter)
        self._budget_needs_the_slow_path(repo, 1000)
        writes = _count_transactions(repo)
        _admit(limiter)
        assert _ledger(repo) == ({"rpm": 2}, {"rpm": 2}, {"weekly": 20}, {})
        assert writes == [1]

    def test_a_slow_rejection_refunds_the_fast_win(self, repo):
        limiter = SyncRateLimiter(repository=repo)
        with limiter.acquire("user", "search", {"rpm": 1}):
            pass
        with limiter.acquire("user", "search", {"rpm": 1}):
            pass
        before = _ledger(repo)
        spent: list[str] = []
        real = repo.speculative_consume

        def speculative_consume(entity_id, resource, *args, **kwargs):
            result = real(entity_id, resource, *args, **kwargs)
            if result.success:
                spent.append(resource)
            return result

        repo.speculative_consume = speculative_consume
        with pytest.raises(RateLimitExceeded) as exc_info:
            _admit(limiter, weekly=5000)
        assert spent == ["search"]
        assert _ledger(repo) == before
        statuses = {(s.resource, s.limit_name, s.exceeded) for s in exc_info.value.statuses}
        assert ("budget", "weekly", True) in statuses
        assert ("search", "rpm", False) in statuses

    def test_a_slow_backend_error_refunds_the_fast_win(self, repo):
        limiter = SyncRateLimiter(repository=repo)
        _admit(limiter)
        self._budget_needs_the_slow_path(repo, 1000)
        before = _ledger(repo)

        def transact_write(items):
            raise RuntimeError("throttled")

        repo.transact_write = transact_write
        with pytest.raises(RateLimiterUnavailable):
            _admit(limiter)
        assert _ledger(repo) == before


def _count_transactions(repo):
    """Record the item count of every transact_write."""
    counts: list[int] = []
    real = repo.transact_write

    def transact_write(items):
        counts.append(len(items))
        return real(items)

    repo.transact_write = transact_write
    return counts


